#include <stdio.h>

typedef struct {
    long long x, y;
} Point;

int main(void) {
    Point p[7];

    for (int i = 0; i < 7; i++) {
        if (scanf("%lld %lld", &p[i].x, &p[i].y) != 2) {
            return 0;
        }
    }

    long long ax = p[1].x - p[0].x;
    long long ay = p[1].y - p[0].y;
    long long bx = p[2].x - p[0].x;
    long long by = p[2].y - p[0].y;

    int valid = 1;

    /* Ângulo agudo e lados iguais P1P2 e P1P3. */
    if (ax * bx + ay * by <= 0 ||
        ax * ax + ay * ay != bx * bx + by * by) {
        valid = 0;
    }

    long long dx = p[2].x - p[1].x;
    long long dy = p[2].y - p[1].y;

    /* Colinearidade de P2, P3, P4 e P5. */
    long long c4 = dx * (p[3].y - p[1].y) - dy * (p[3].x - p[1].x);
    long long c5 = dx * (p[4].y - p[1].y) - dy * (p[4].x - p[1].x);
    if (c4 != 0 || c5 != 0) {
        valid = 0;
    }

    /* Pontos médios coincidentes. */
    if (p[1].x + p[2].x != p[3].x + p[4].x ||
        p[1].y + p[2].y != p[3].y + p[4].y) {
        valid = 0;
    }

    long long tx = p[4].x - p[3].x;
    long long ty = p[4].y - p[3].y;

    /* P2P3 é maior que P4P5. */
    if (dx * dx + dy * dy <= tx * tx + ty * ty) {
        valid = 0;
    }

    long long v6x = p[5].x - p[3].x;
    long long v6y = p[5].y - p[3].y;
    long long v7x = p[6].x - p[4].x;
    long long v7y = p[6].y - p[4].y;

    /* Perpendicularidade e comprimentos iguais. */
    if (dx * v6x + dy * v6y != 0 ||
        dx * v7x + dy * v7y != 0 ||
        v6x * v6x + v6y * v6y != v7x * v7x + v7y * v7y) {
        valid = 0;
    }

    /* O segmento P1P6 encontra a reta P2P3 em um único ponto. */
    long long side1 = dx * (p[0].y - p[1].y) - dy * (p[0].x - p[1].x);
    long long side6 = dx * (p[5].y - p[1].y) - dy * (p[5].x - p[1].x);

    if ((side1 == 0 && side6 == 0) ||
        (side1 != 0 && side6 != 0 && ((side1 > 0) == (side6 > 0)))) {
        valid = 0;
    }

    printf("%c\n", valid ? 'S' : 'N');
    return 0;
}
